{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "What is the objective of this production plan — to maximize total profit (unit price minus raw material cost minus processing cost), to maximize total revenue, or to minimize total processing cost?"
  ],
  "rationale": "The response asks for a single policy choice among three mutually exclusive objectives, which constitutes one semantically independent clarification question."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Are there any demand limits or minimum production requirements for the three products, or can each product be produced in any non-negative quantity as long as equipment hours are not exceeded?"
  ],
  "rationale": "The response asks a single clarification question regarding the existence of demand limits or minimum production requirements versus unrestricted non-negative production."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Are the production quantities for the three products required to be whole numbers (integer pieces), or can they be treated as continuous values?"
  ],
  "rationale": "The response contains a single clarification question asking for a policy choice regarding the variable type (integer vs. continuous)."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "For the processing cost, is the cost per machine hour multiplied by the processing time per piece (in hours) to get the cost per piece, so that total processing cost equals the sum over all equipment of (hours used on that equipment) times (its cost per hour)?"
  ],
  "rationale": "The response contains a single clarification question asking for confirmation of the specific calculation method for processing costs."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Since each product must go through both stage A and stage B, is the quantity of each product that enters stage A required to equal the quantity that completes stage B (i.e., no work-in-progress or leftover units at either stage)?"
  ],
  "rationale": "The response contains a single clarification question asking whether flow balance is required between stages, with no other independent requests."
}

{
  "action": "question",
